DROP TABLE IF EXISTS TBL_PENDING_DATA;

CREATE TABLE TBL_PENDING_DATA (
    PENDING_ID                BIGINT          NOT NULL PRIMARY KEY,
    BUSINESS_NO               VARCHAR(64),
    BUSINESS_TYPE             VARCHAR(32),
    SETTLEMENT_AMOUNT         DECIMAL(20,2),
    CURRENCY_CODE             VARCHAR(8),
    COUNTERPARTY_ACCOUNT      VARCHAR(64),
    COUNTERPARTY_NAME         VARCHAR(128),
    COUNTERPARTY_BANK         VARCHAR(128),
    PRIORITY                  VARCHAR(16),
    EXPECTED_SETTLEMENT_DATE  DATE,
    ACTUAL_SETTLEMENT_DATE    DATE,
    SETTLEMENT_STATUS         VARCHAR(32),
    APPROVAL_STATUS           VARCHAR(32),
    FAILURE_REASON            VARCHAR(512),
    RETRY_COUNT               INT             DEFAULT 0,
    BUSINESS_DESCRIPTION      VARCHAR(512),
    ATTACHMENT_PATH           VARCHAR(512),
    REMARK                    VARCHAR(512),
    DELETE_FLAG               INT             DEFAULT 0,
    CREATE_BY                 BIGINT,
    CREATE_BY_NAME            VARCHAR(64),
    CREATE_TIME               TIMESTAMP,
    UPDATE_BY                 BIGINT,
    UPDATE_BY_NAME            VARCHAR(64),
    UPDATE_TIME               TIMESTAMP,
    ORG_ID                    BIGINT,
    ORG_NAME                  VARCHAR(128),
    APPROVAL_BY               BIGINT,
    APPROVAL_BY_NAME          VARCHAR(64),
    APPROVAL_TIME             TIMESTAMP,
    APPROVAL_OPINION          VARCHAR(512)
);

