 -- 4. TBL_MONITORING（结算监控）
 -- ============================================================
 DROP TABLE IF EXISTS TBL_MONITORING;
 
 CREATE TABLE TBL_MONITORING (
     MONITORING_ID           BIGINT          NOT NULL PRIMARY KEY,
     MONITOR_TYPE            VARCHAR(32),
     MONITOR_NAME            VARCHAR(128),
     ALERT_LEVEL             VARCHAR(16),
     ALERT_MESSAGE           VARCHAR(512),
     TRANSACTION_COUNT       INT             DEFAULT 0,
     SUCCESS_COUNT           INT             DEFAULT 0,
     FAILED_COUNT            INT             DEFAULT 0,
     SUCCESS_RATE            DECIMAL(5,2),
     AVG_PROCESSING_TIME     INT,
     MAX_PROCESSING_TIME     INT,
     MIN_PROCESSING_TIME     INT,
     TOTAL_AMOUNT            DECIMAL(20,2),
     HEALTH_SCORE            DECIMAL(5,2),
     SYSTEM_LOAD             DECIMAL(5,2),
     MEMORY_USAGE            DECIMAL(5,2),
     CPU_USAGE               DECIMAL(5,2),
     DISK_USAGE              DECIMAL(5,2),
     NETWORK_LATENCY         INT,
     IS_ALERT_SENT           INT             DEFAULT 0,
     ALERT_SENT_TIME         TIMESTAMP,
     MONITOR_TIME            TIMESTAMP,
     MONITOR_DESCRIPTION     VARCHAR(512),
     REMARK                  VARCHAR(512),
     DELETE_FLAG             INT             DEFAULT 0,
     CREATE_BY               BIGINT,
     CREATE_BY_NAME          VARCHAR(64),
     CREATE_TIME             TIMESTAMP,
     UPDATE_BY               BIGINT,
     UPDATE_BY_NAME          VARCHAR(64),
     UPDATE_TIME             TIMESTAMP,
     ORG_ID                  BIGINT,
     ORG_NAME                VARCHAR(128)
 );
 
