-- 2. TBL_BANK_INTERFACE_CONFIG（银企联配置）
-- ============================================================
DROP TABLE IF EXISTS TBL_BANK_INTERFACE_CONFIG;

CREATE TABLE TBL_BANK_INTERFACE_CONFIG (
    CONFIG_ID               BIGINT          NOT NULL PRIMARY KEY,
    BANK_NAME               VARCHAR(128),
    BANK_CODE               VARCHAR(32),
    INTERFACE_TYPE          VARCHAR(32),
    INTERFACE_VERSION       VARCHAR(16),
    INTERFACE_NAME          VARCHAR(128),
    PROTOCOL_TYPE           VARCHAR(16),
    API_URL                 VARCHAR(512),
    ENDPOINT_URL            VARCHAR(512),
    HEALTH_CHECK_URL        VARCHAR(512),
    AUTH_TYPE               VARCHAR(16),
    AUTH_TOKEN              VARCHAR(512),
    AUTH_CONFIG             VARCHAR(1024),
    SSL_CONFIG              VARCHAR(1024),
    CONNECTION_TIMEOUT      INT             DEFAULT 30,
    READ_TIMEOUT            INT             DEFAULT 60,
    MAX_RETRY_COUNT         INT             DEFAULT 3,
    PRIORITY                INT             DEFAULT 5,
    LOAD_BALANCE_WEIGHT     INT             DEFAULT 10,
    HEALTH_CHECK_INTERVAL   INT             DEFAULT 60,
    HEALTH_STATUS           VARCHAR(16),
    IS_ENABLED              INT             DEFAULT 1,
    LAST_CONNECT_TIME       TIMESTAMP,
    LAST_CONNECT_STATUS     VARCHAR(16),
    LAST_CONNECT_MESSAGE    VARCHAR(512),
    LAST_HEALTH_CHECK_TIME  TIMESTAMP,
    CONFIG_DESCRIPTION      VARCHAR(512),
    REMARK                  VARCHAR(512),
    DELETE_FLAG             INT             DEFAULT 0,
    CREATE_BY               BIGINT,
    CREATE_BY_NAME          VARCHAR(64),
    CREATE_TIME             TIMESTAMP,
    UPDATE_BY               BIGINT,
    UPDATE_BY_NAME          VARCHAR(64),
    UPDATE_TIME             TIMESTAMP,
    ORG_ID                  BIGINT,
    ORG_NAME                VARCHAR(128)
);

