-- ============================================================
-- 3. TBL_PROCESSING_RECORD（结算处理记录）
-- ============================================================
DROP TABLE IF EXISTS TBL_PROCESSING_RECORD;

CREATE TABLE TBL_PROCESSING_RECORD (
    RECORD_ID               BIGINT          NOT NULL PRIMARY KEY,
    PENDING_ID              BIGINT,
    BUSINESS_NO             VARCHAR(64),
    BATCH_NO                VARCHAR(64),
    PROCESS_TYPE            VARCHAR(32),
    PROCESSING_STATUS       VARCHAR(32),
    BANK_INTERFACE_ID       BIGINT,
    BANK_TRANSACTION_NO     VARCHAR(128),
    TRANSACTION_COUNT       INT             DEFAULT 0,
    SUCCESS_COUNT           INT             DEFAULT 0,
    FAILED_COUNT            INT             DEFAULT 0,
    AVG_PROCESSING_TIME     INT,
    PROCESSING_DURATION     INT,
    START_TIME              TIMESTAMP,
    END_TIME                TIMESTAMP,
    ERROR_CODE              VARCHAR(32),
    ERROR_MESSAGE           VARCHAR(512),
    MAX_RETRY_COUNT         INT             DEFAULT 3,
    RETRY_COUNT             INT             DEFAULT 0,
    NEXT_RETRY_TIME         TIMESTAMP,
    BANK_REQUEST            CLOB,
    BANK_RESPONSE           CLOB,
    RECORD_DESCRIPTION      VARCHAR(512),
    REMARK                  VARCHAR(512),
    DELETE_FLAG             INT             DEFAULT 0,
    CREATE_BY               BIGINT,
    CREATE_BY_NAME          VARCHAR(64),
    CREATE_TIME             TIMESTAMP,
    UPDATE_BY               BIGINT,
    UPDATE_BY_NAME          VARCHAR(64),
    UPDATE_TIME             TIMESTAMP,
    ORG_ID                  BIGINT,
    ORG_NAME                VARCHAR(128)
);

